import{_ as i,o as t,c as e,ak as s}from"./chunks/framework.DKi5cyCJ.js";const u=JSON.parse('{"title":"SVN → GitLab · 03 推送到 GitLab","description":"在本地 GitLab 建 Private 空项目，经 HTTP 隧道 push 全部分支与标签并验收网页历史。 在 SVN 迁 Git 第 3 步、svn-to-git-03、推送到 GitLab 时使用。","frontmatter":{"name":"svn-to-git-03-push-gitlab","description":"在本地 GitLab 建 Private 空项目，经 HTTP 隧道 push 全部分支与标签并验收网页历史。 在 SVN 迁 Git 第 3 步、svn-to-git-03、推送到 GitLab 时使用。"},"headers":[],"relativePath":"public/assets/attachments/gitlab-skills/svn-to-git-03-push-gitlab/SKILL.md","filePath":"public/assets/attachments/gitlab-skills/svn-to-git-03-push-gitlab/SKILL.md"}'),o={name:"public/assets/attachments/gitlab-skills/svn-to-git-03-push-gitlab/SKILL.md"};function l(n,a,h,d,r,p){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="svn-→-gitlab-·-03-推送到-gitlab" tabindex="-1">SVN → GitLab · 03 推送到 GitLab <a class="header-anchor" href="#svn-→-gitlab-·-03-推送到-gitlab" aria-label="Permalink to &quot;SVN → GitLab · 03 推送到 GitLab&quot;">​</a></h1><h2 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h2><ul><li>02 完成；本地 <code>%WORK_ROOT%\\%LOCAL_DIR%</code> 可 <code>git log</code>。</li><li>变量：<code>TARGET_GROUP</code>（形如 <code>is20pro/PC</code>）、<code>TARGET_PROJECT</code>、<code>GIT_HTTP_TUNNEL</code>、<code>GITLAB_HOST</code>。</li><li>产品 Group 与子组 <strong><code>PC</code>/<code>MC</code>/<code>MX</code> 已预先建好</strong>；有 Maintainer 或更高权限 + PAT。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_0-若子组尚未建立-批次开始时做一次" tabindex="-1">0) 若子组尚未建立（批次开始时做一次） <a class="header-anchor" href="#_0-若子组尚未建立-批次开始时做一次" aria-label="Permalink to &quot;0) 若子组尚未建立（批次开始时做一次）&quot;">​</a></h3><p>网页：New Group → <code>&lt;产品&gt;</code>（Private）→ 在组内 New subgroup → 依次建 <code>PC</code>、<code>MC</code>、<code>MX</code>（Private）。<br> 确认路径可打开：<code>http://$GITLAB_HOST/&lt;产品&gt;/PC</code> 等。</p><h3 id="_1-建空项目-private-无-readme" tabindex="-1">1) 建空项目（Private，无 README） <a class="header-anchor" href="#_1-建空项目-private-无-readme" aria-label="Permalink to &quot;1) 建空项目（Private，无 README）&quot;">​</a></h3><p>网页：进入目标子组（如 <code>&lt;产品&gt;/MX</code>）→ New project → 空白 → Private → <strong>不</strong>初始化 README。</p><p>或 API（示例，Token 勿入库）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v4/projects</span></span>
<span class="line"><span>{ &quot;name&quot;: &quot;&lt;显示名&gt;&quot;, &quot;path&quot;: &quot;&lt;TARGET_PROJECT&gt;&quot;, &quot;namespace_id&quot;: &lt;组ID&gt;, &quot;visibility&quot;: &quot;private&quot;, &quot;initialize_with_readme&quot;: false }</span></span></code></pre></div><p>默认分支稍后以推送的 <code>main</code> 为准。</p><h3 id="_2-开-http-隧道-本环境必做" tabindex="-1">2) 开 HTTP 隧道（本环境必做） <a class="header-anchor" href="#_2-开-http-隧道-本环境必做" aria-label="Permalink to &quot;2) 开 HTTP 隧道（本环境必做）&quot;">​</a></h3><p>开发机运行项目根目录 <code>git_http_tunnel.bat</code>，保持窗口不关。</p><p>推送 URL 基址：<code>%GIT_HTTP_TUNNEL%</code>（默认 <code>http://127.0.0.1:18173</code>），<strong>不要</strong>对 <code>http://%GITLAB_HOST%</code> 直连 <code>git.exe</code>（易 400）。</p><h3 id="_3-添加-remote-并推送" tabindex="-1">3) 添加 remote 并推送 <a class="header-anchor" href="#_3-添加-remote-并推送" aria-label="Permalink to &quot;3) 添加 remote 并推送&quot;">​</a></h3><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /d </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%WORK_ROOT%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%LOCAL_DIR%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git remote remove origin </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nul</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git remote add origin </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%GIT_HTTP_TUNNEL%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%TARGET_GROUP%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%TARGET_PROJECT%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.git&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git push -u origin --all</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git push origin --tags</span></span></code></pre></div><p>认证：用户名 <code>oauth2</code>，密码 = PAT（<code>write_repository</code>）。</p><h3 id="_4-保护分支-与现网一致" tabindex="-1">4) 保护分支（与现网一致） <a class="header-anchor" href="#_4-保护分支-与现网一致" aria-label="Permalink to &quot;4) 保护分支（与现网一致）&quot;">​</a></h3><p>Project → Settings → Repository → Protected branches：</p><ul><li><code>main</code>：禁止 force push；Maintainer 合并</li><li><code>release/*</code>：同上</li></ul><h3 id="_5-验收" tabindex="-1">5) 验收 <a class="header-anchor" href="#_5-验收" aria-label="Permalink to &quot;5) 验收&quot;">​</a></h3><ul><li>[ ] 网页 Commits 能看到历史（不止 1 条初始提交）</li><li>[ ] 文件树与 SVN trunk（或 L2 根）抽样一致</li><li>[ ] 另开终端经隧道 <code>git clone</code> 成功（可选）</li></ul><h2 id="完成门槛" tabindex="-1">完成门槛 <a class="header-anchor" href="#完成门槛" aria-label="Permalink to &quot;完成门槛&quot;">​</a></h2><ul><li>[ ] Private 空仓已建且已 push <code>--all</code> / <code>--tags</code></li><li>[ ] 保护分支已设或已记录待设</li><li>[ ] 网页历史验收通过</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>试迁：请用户确认后，对其余清单项重复 01→03</li><li>全部迁完或试迁通过后 → <code>svn-to-git-04-cutover</code></li></ul>`,26)])])}const k=i(o,[["render",l]]);export{u as __pageData,k as default};
